package dev.pocketengine.phone.observation;
import static org.junit.Assert.*;
import android.app.Application;import android.os.*;import java.time.Duration;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public final class DelayedInputReadbackTest {
 @Test public void delayedSampleSeesRollbackOnceAndReleasesOriginalHandle()throws Exception {for(boolean rollback:new boolean[]{false,true}){AtomicReference<String> value=new AtomicReference<>("中文目标");AtomicInteger reads=new AtomicInteger(),released=new AtomicInteger();DelayedInputReadback delayed=new DelayedInputReadback();delayed.schedule(new Handler(Looper.getMainLooper()),()->{reads.incrementAndGet();return PhoneActionEffects.inputReadback(value.get(),"中文目标",false);},released::incrementAndGet);assertEquals("exact_match",PhoneActionEffects.inputReadback(value.get(),"中文目标",false).getString("status"));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(400));assertEquals(0,reads.get());if(rollback)value.set("旧值");Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(200));JSONObject receipt=delayed.attach(new JSONObject().put("accepted",true));assertEquals(rollback?"mismatch":"exact_match",receipt.getJSONObject("delayedTextReadback").getString("status"));assertEquals(1,reads.get());assertEquals(1,released.get());assertFalse(receipt.getBoolean("automaticReplayAllowed"));}}
 @Test public void removedOriginalNodeIsUnavailableNotReplacedByAnotherField()throws Exception {DelayedInputReadback delayed=new DelayedInputReadback();AtomicInteger released=new AtomicInteger();delayed.schedule(new Handler(Looper.getMainLooper()),()->{throw new IllegalStateException("detached original");},released::incrementAndGet);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals("unavailable",delayed.attach(new JSONObject()).getJSONObject("delayedTextReadback").getString("status"));assertEquals(1,released.get());JSONObject secret=PhoneActionEffects.inputReadback("must-not-echo","must-not-echo",true);assertFalse(secret.toString().contains("must-not-echo"));assertEquals("owner_private_not_echoed",secret.getString("status"));}
 @Test public void uiTimerHandsBlockingReadToBoundedWorkerAndRejectsWithoutLeakingRetainedHandle()throws Exception {
  PhoneReadGate gate=new PhoneReadGate(100);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),finished=new CountDownLatch(1);AtomicInteger freed=new AtomicInteger(),ui=new AtomicInteger();DelayedInputReadback first=new DelayedInputReadback();
  try{first.schedule(new Handler(Looper.getMainLooper()),gate.executor(),()->{entered.countDown();release.await();return PhoneActionEffects.unavailableReadback("fixture_returned");},()->{freed.incrementAndGet();finished.countDown();});Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertTrue(entered.await(1,TimeUnit.SECONDS));
   new Handler(Looper.getMainLooper()).post(ui::incrementAndGet);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,ui.get());
   DelayedInputReadback second=new DelayedInputReadback();second.schedule(new Handler(Looper.getMainLooper()),gate.executor(),()->{fail("single flight must reject a second read");return null;},freed::incrementAndGet);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals("unavailable",second.attach(new JSONObject()).getJSONObject("delayedTextReadback").getString("status"));assertEquals(1,freed.get());
  }finally{release.countDown();assertTrue(finished.await(1,TimeUnit.SECONDS));}assertEquals(2,freed.get());
 }
}
